// Package apigen carries the generated contract artifacts: the embedded
// OpenAPI spec tree (synced from api/ by api/gen-root-paths.mjs) and the Go
// types generated by oapi-codegen. Regenerate with `make generate`; contract
// tests fail if committed artifacts drift from api/.
package apigen

import (
	"embed"
	"net/url"

	"github.com/getkin/kin-openapi/openapi3"
)

//go:embed spec
var SpecFS embed.FS

// Load parses the embedded OpenAPI document with all references resolved
// from the embedded tree (no filesystem access at runtime).
func Load() (*openapi3.T, error) {
	loader := openapi3.NewLoader()
	loader.IsExternalRefsAllowed = true
	loader.ReadFromURIFunc = func(_ *openapi3.Loader, u *url.URL) ([]byte, error) {
		return SpecFS.ReadFile("spec/" + u.Path)
	}
	doc, err := loader.LoadFromURI(&url.URL{Scheme: "embed", Path: "openapi.yaml"})
	if err != nil {
		return nil, err
	}
	if err := doc.Validate(loader.Context); err != nil {
		return nil, err
	}
	return doc, nil
}
